    summaryShort: "One of North America's truest Mediterranean pockets — south-facing coast with mountain shelter behind.",
    summaryImmersive: "Santa Barbara's orientation is a geographic accident of rare value. The coastline turns east-west for a stretch here, leaving the city facing due south, backed by the Santa Ynez Mountains rising to 1200 m within 10 km. The range sheds cold winter storms; the sea moderates summer heat. The result is genuine Mediterranean climate — mild dry summers, soft wet winters, and some of the most generous light in North America. Citrus and avocados thrive within the city; vineyards thrive in the nearby valleys. When 'June gloom' clamps the rest of coastal California, Santa Barbara often sits in sun.",
