    summaryImmersive: "Fifty miles downwind of the Cascade crest — but in climate terms a different continent. Wenatchee sees around 240 mm of annual precipitation where Stevens Pass, 80 km upwind, gets over 2500 mm. The Columbia and Wenatchee rivers converge here in a broad valley whose thermal mass moderates the worst extremes while the surrounding terraces gather every bit of sunshine the Pacific Northwest can spare. The result is one of the continent's great tree-fruit regions: apples, cherries, pears, and increasingly wine grapes thrive where Seattle's weather cannot.",
