        summer: "Cool and precious — highs near 22°C on the rare sunny afternoon, marine layer returning by evening, and July the driest month that still feels like a rainforest.",
        autumn: "The big rains return — October and November can each exceed 300 mm, rivers swell, and the valley reads as the Pacific's receiving basin.",
