        summer: "Warm, smoky, river-bright — highs near 29°C, afternoon thunderstorms, and wildfire smoke that can pool in the basin for days when high pressure locks the valleys.",
        autumn: "Color and first inversions — maples and cottonwoods flare along the rivers, the first cold-air pooling returns at night, and the community prepares for another winter of smoke and snow.",
