    lat: 39.0500, lon: -79.4500, elevationM: 980,
    reliefContext: "High Allegheny plateau basin; the highest valley east of the Mississippi, ringed by ridges, with cold-air pooling unusual for the Appalachians.",
    biome: "Boreal relict: balsam fir, red spruce, cranberry bogs", koppen: "Dfb (near-subarctic anomaly)",
