      sunshinePct: [82, 85, 88, 91, 93, 94, 92, 92, 92, 89, 84, 81],
      annualPrecipMm: 63, frostFreeDays: 340, hardinessZone: "10a", diurnalSummerC: 16, diurnalWinterC: 15,
