    elevationM: 400,
    reliefContext: "A ~320 km north–south band of chert-capped Permian limestone rising 60–100 m above adjacent lowlands — the rock was too hard and cherty to be plowed, which is the entire reason the prairie survived here.",
    biome: "Tallgrass prairie (big bluestem, Indiangrass, switchgrass) — the largest intact tract remaining in North America",
