    elevationM: 430,
    reliefContext: "Perched at the northern rim of the Springfield Plateau where ~200 m of Ordovician carbonate strata are exposed in a tight knot of spring-fed hollows. The town itself is built on three steeply dissected ridges with 90 m of relief in less than 500 m of horizontal distance.",
    biome: "Oak-hickory upland forest with mesic cove-hardwood seeps",
