        summer: "Cool and sweater-friendly — highs near 19°C, foggy Junes, and summer afternoons that rarely tax a light jacket.",
        autumn: "Storm season returns — October rains exceed 140 mm, gales rake the headlands, and the Chetco effect makes winter headlines when it fires.",
